<template>
  <section class="model-gateway">
    <header class="gateway-header"><div><p class="eyebrow">MODEL CENTER / GATEWAY</p><h1>统一模型网关</h1><p>一个 SmartOps Key 访问已授权的模型分组，Provider 密钥留在服务端。</p></div><span class="gateway-state"><i />FOUNDATION</span></header>
    <nav class="gateway-tabs" aria-label="模型网关视图"><button v-for="tab in tabs" :key="tab.id" :class="{ active: view === tab.id }" type="button" @click="select(tab.id)">{{ tab.label }}<small>{{ tab.cn }}</small></button></nav>
    <div v-if="view === 'overview'" class="gateway-grid"><section class="gateway-panel gateway-panel--wide"><p class="eyebrow">OPENAI COMPATIBLE</p><h2>统一调用入口</h2><code>POST /v1/chat/completions</code><p>网关按模型组路由，并记录不含请求正文的调用元数据。</p><div class="gateway-flow"><span>VIRTUAL KEY</span><b>→</b><span>MODEL GROUP</span><b>→</b><span>PROVIDER</span></div></section><section class="gateway-panel"><p class="eyebrow">CURRENT SPACE</p><h2>模型接入</h2><p>现有模型连接继续使用 Astra6 的 MODELS 导航。</p><RouterLink to="/model-settings">打开模型接入 →</RouterLink></section><section class="gateway-panel"><p class="eyebrow">GOVERNANCE</p><h2>权限与审计</h2><p>虚拟 Key、模型分组和 Provider 凭据在服务端管理。</p></section></div>
    <section v-else-if="view === 'keys'" class="gateway-panel gateway-management"><div class="management-heading"><div><p class="eyebrow">VIRTUAL KEYS</p><h2>虚拟 Key 管理</h2><p>完整 Key 只在创建时显示，列表仅保留前缀和状态。</p></div><button class="gateway-action" type="button" :disabled="keySaving" @click="createKey">{{ keySaving ? '创建中' : '创建个人 Key' }}</button></div><p v-if="keyNotice" class="gateway-notice">{{ keyNotice }}</p><p v-if="keyError" class="gateway-error">{{ keyError }}</p><div v-if="newKey" class="new-key"><span>新 Key（仅显示一次）</span><code>{{ newKey }}</code><button type="button" @click="copyKey">复制</button></div><div v-if="keysLoading" class="gateway-empty-state">正在读取 Key...</div><div v-else-if="keys.length" class="key-list"><div v-for="item in keys" :key="item.id" class="key-row"><div><strong>{{ item.name }}</strong><code>{{ item.prefix }}...</code><small>{{ quotaText(item) }}</small></div><span :class="['key-status', { revoked: item.revoked }]">{{ item.revoked ? 'REVOKED' : 'ACTIVE' }}</span><div v-if="!item.revoked" class="key-actions"><GatewayQuotaEditor :item="item" @saved="applyQuota(item, $event)" /><button type="button" :disabled="keyBusy === item.id" @click="revokeKey(item)">{{ keyBusy === item.id ? '处理中' : '撤销' }}</button></div></div></div><div v-else class="gateway-empty-state">还没有个人 Key。</div></section>
    <section v-else-if="view === 'audit'" class="gateway-panel gateway-management"><div class="management-heading"><div><p class="eyebrow">AUDIT / HEALTH</p><h2>网关运行观测</h2><p>近 24 小时统计和路由状态，仅展示脱敏元数据。</p></div><button class="gateway-action" type="button" :disabled="auditLoading" @click="loadAudit">刷新</button></div><p v-if="auditError" class="gateway-error">{{ auditError }}</p><div class="audit-metrics"><div><span>REQUESTS</span><strong>{{ audit.summary.calls }}</strong></div><div><span>SUCCESS</span><strong>{{ successRate }}%</strong></div><div><span>AVG LATENCY</span><strong>{{ audit.summary.latencyMs }} ms</strong></div><div><span>TOKENS</span><strong>{{ audit.summary.tokens }}</strong></div></div><div class="route-search"><input v-model.trim="routeSlug" placeholder="模型组标识，例如 ops-default"><button type="button" :disabled="!routeSlug" @click="loadRouteHealth">查看路由</button></div><p v-if="routeError" class="gateway-error">{{ routeError }}</p><div v-if="routeHealth.length" class="key-list"><div v-for="item in routeHealth" :key="item.id" class="key-row"><div><strong>连接 #{{ item.connectionId }}</strong><code>优先级 {{ item.priority }} · 失败 {{ item.failureCount }} 次</code></div><span :class="['key-status', { revoked: !item.healthy }]">{{ item.healthy ? 'READY' : 'OPEN' }}</span></div></div><div class="key-list"><div v-for="entry in audit.recent" :key="entry.group + entry.createdAt" class="key-row"><div><strong>{{ entry.group }}</strong><code>{{ entry.createdAt }}<template v-if="entry.configVersion"> · 配置 v{{ entry.configVersion }}</template></code></div><span :class="['key-status', { revoked: entry.status !== 'SUCCESS' }]">{{ entry.status }}</span><span>{{ entry.durationMs }} ms</span></div></div><p v-if="!audit.recent.length && !auditLoading" class="gateway-empty-state">暂无调用记录。</p></section>
    <section v-else-if="view === 'releases'" class="gateway-panel gateway-management"><div class="management-heading"><div><p class="eyebrow">CONFIG RELEASES</p><h2>配置版本与回滚</h2><p>工作区改动先生成草稿，通过闸门校验并发布后才进入请求链路；支持按比例灰度与多级审批。</p></div><div class="key-actions"><button class="gateway-action" type="button" :disabled="versionBusy === 'create'" @click="createVersion">{{ versionBusy === 'create' ? '生成中' : '生成草稿' }}</button><button class="gateway-action" type="button" :disabled="versionLoading" @click="loadVersions">刷新</button></div></div><p v-if="currentConfig.version" class="gateway-notice">当前生效 v{{ currentConfig.version }} · {{ currentConfig.summary }}<template v-if="currentConfig.canaryVersion"> · 灰度 v{{ currentConfig.canaryVersion }} 承接 {{ currentConfig.canaryPercent }}% 流量</template></p><p v-else class="gateway-notice">尚未发布任何配置版本，网关暂按工作区直读。</p><p class="gateway-notice">发布审批：{{ requiredApprovals > 0 ? `需 ${requiredApprovals} 级审批，创建人不能审批自己的版本` : '未开启审批，管理员可直接发布' }}<template v-if="currentConfig.approvers && currentConfig.approvers.length"> · 审批人：{{ currentConfig.approvers.join('、') }}</template></p><p v-if="versionNotice" class="gateway-notice">{{ versionNotice }}</p><p v-if="versionError" class="gateway-error">{{ versionError }}</p><div v-if="versionLoading" class="gateway-empty-state">正在读取版本...</div><div v-else-if="versions.length" class="key-list"><div v-for="item in versions" :key="item.id" class="key-row"><div><strong>v{{ item.version }}</strong><code>{{ item.summary }}</code><small>{{ item.createdAt }}<template v-if="item.rolloutPercent && item.rolloutPercent < 100"> · 灰度 {{ item.rolloutPercent }}%</template></small></div><span :class="['key-status', { revoked: item.status !== 'ACTIVE' }]">{{ statusText(item) }}</span><div class="key-actions"><button type="button" @click="inspectVersion(item)">差异</button><button v-if="item.status === 'DRAFT' && !requiredApprovals" type="button" :disabled="versionBusy === item.id" @click="activateVersion(item)">发布</button><button v-if="item.status === 'DRAFT' && requiredApprovals" type="button" :disabled="versionBusy === item.id" @click="submitVersion(item)">提交审批</button><button v-if="item.status === 'PENDING_APPROVAL'" type="button" :disabled="versionBusy === item.id" @click="approveVersion(item)">通过</button><button v-if="item.status === 'PENDING_APPROVAL'" type="button" :disabled="versionBusy === item.id" @click="rejectVersion(item)">驳回</button><button v-if="item.status === 'ACTIVE' && item.rolloutPercent < 100" type="button" :disabled="versionBusy === item.id" @click="compareVersion(item)">健康对比</button><button v-if="item.status === 'ACTIVE' && item.rolloutPercent < 100" type="button" :disabled="versionBusy === item.id" @click="promoteVersion(item)">转全量</button><button v-if="['ACTIVE', 'SUPERSEDED', 'REJECTED'].includes(item.status)" type="button" :disabled="versionBusy === item.id" @click="rollbackVersion(item)">回滚</button><button v-if="['DRAFT', 'REJECTED'].includes(item.status)" type="button" :disabled="versionBusy === item.id" @click="deleteVersion(item)">删除</button></div></div></div><p v-else class="gateway-empty-state">还没有配置版本。</p><div v-if="comparison" class="version-detail"><p class="eyebrow">CANARY HEALTH · {{ comparison.windowMinutes }} MIN</p><p class="gateway-notice">建议：{{ verdictText(comparison.verdict) }}</p><div class="audit-metrics"><div><span>CANARY v{{ comparison.version }}</span><strong>{{ comparison.canary.successRate }}%</strong><small>{{ comparison.canary.calls }} 次 · 平均 {{ comparison.canary.avgLatencyMs }} ms</small></div><div><span>FULL v{{ comparison.stableVersion || '-' }}</span><strong>{{ comparison.stable.successRate }}%</strong><small>{{ comparison.stable.calls }} 次 · 平均 {{ comparison.stable.avgLatencyMs }} ms</small></div></div><p v-for="reason in comparison.reasons" :key="reason" class="gateway-notice">{{ reason }}</p></div><div v-if="selectedVersion" class="version-detail"><p class="eyebrow">GATE / DIFF</p><p v-if="selectedVersion.gate && !selectedVersion.gate.passed" class="gateway-error">闸门未通过：{{ (selectedVersion.gate.errors || []).join('；') }}</p><p v-else class="gateway-notice">闸门校验通过</p><p v-if="selectedVersion.rejectionComment" class="gateway-error">驳回原因：{{ selectedVersion.rejectionComment }}</p><div v-if="selectedVersion.diff && selectedVersion.diff.changes && selectedVersion.diff.changes.length" class="key-list"><div v-for="change in selectedVersion.diff.changes" :key="change.type + change.key" class="key-row"><div><strong>{{ change.type }}</strong><code>{{ change.key }}</code></div><span>{{ (change.fields || []).join(' · ') }}</span></div></div><p v-else class="gateway-empty-state">与对比版本无差异。</p><div v-if="selectedVersion.approvals && selectedVersion.approvals.length" class="key-list"><div v-for="(entry, index) in selectedVersion.approvals" :key="index" class="key-row"><div><strong>{{ entry.action }}</strong><code>审批人 #{{ entry.approverId }}</code></div><span>{{ entry.comment || '无备注' }}</span><small>{{ entry.createdAt }}</small></div></div></div></section>
    <section v-else class="gateway-panel gateway-management"><div class="management-heading"><div><p class="eyebrow">MODEL GROUPS</p><h2>模型分组与路由</h2><p>模型组使用已有模型连接，并在同一操作区配置 24 小时配额。</p></div><RouterLink class="gateway-link" to="/model-settings">管理模型连接 →</RouterLink></div><GatewayGroupForm :saving="groupSaving" @submit="saveGroup" /><p v-if="groupNotice" class="gateway-notice">{{ groupNotice }}</p><p v-if="groupError" class="gateway-error">{{ groupError }}</p></section>
    <section v-if="view === 'audit' && routeHealth.length" class="gateway-panel gateway-management route-admin-panel"><div class="management-heading"><div><p class="eyebrow">ROUTE CONTROL</p><h2>路由控制</h2><p>仅管理当前模型组查询到的路由。</p></div></div><div class="key-list"><div v-for="item in routeHealth" :key="`control-${item.id}`" class="key-row"><div><strong>连接 #{{ item.connectionId }}</strong><code>优先级 {{ item.priority }} · 权重 {{ item.weight }}</code></div><span :class="['key-status', { revoked: !item.enabled || !item.healthy }]">{{ item.enabled ? (item.healthy ? 'READY' : 'OPEN') : 'DISABLED' }}</span><div class="key-actions"><button type="button" @click="toggleRoute(item)">{{ item.enabled ? '禁用' : '启用' }}</button><button type="button" @click="removeRoute(item)">删除</button></div></div></div></section>
    <section v-if="view === 'groups'" class="gateway-panel gateway-management group-list-panel"><div class="management-heading"><div><p class="eyebrow">PERSONAL GROUPS</p><h2>我的模型组</h2><p>模型组和 Provider 路由仅对当前用户可见。</p></div><button class="gateway-action" type="button" @click="loadGroups">刷新</button></div><div v-if="groupsLoading" class="gateway-empty-state">正在读取模型组...</div><div v-else-if="groups.length" class="group-list"><article v-for="item in groups" :key="item.slug" class="group-item"><div class="group-item__head"><div><strong>{{ item.name }}</strong><code>{{ item.slug }}</code></div><span :class="['key-status', { revoked: !item.enabled }]">{{ item.enabled ? 'ACTIVE' : 'DISABLED' }}</span><div class="key-actions"><button type="button" :disabled="groupBusy === item.slug" @click="renameGroup(item)">重命名</button><button type="button" :disabled="groupBusy === item.slug" @click="removeGroup(item)">删除</button></div></div><p class="group-meta">{{ quotaText(item) }}</p><div class="route-inline"><input v-model.number="routeDrafts[item.id].priority" type="number" min="0" max="10000" placeholder="优先级"><input v-model.number="routeDrafts[item.id].weight" type="number" min="1" max="1000" placeholder="权重"><button type="button" @click="editRoute(item, routeDrafts[item.id])">保存路由参数</button></div></article></div><p v-else class="gateway-empty-state">还没有个人模型组。</p></section>
  <AgentCopilotDock
    section="模型网关"
    :entity="{ type: 'connection', id: routeHealth?.[0]?.connectionId || routeSlug }"
  />
  </section>
</template>
<script setup>
import AgentCopilotDock from '../../components/agent/AgentCopilotDock.vue'
import { computed, onMounted, ref } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import GatewayQuotaEditor from '../../components/model/GatewayQuotaEditor.vue'
import GatewayGroupForm from '../../components/model/GatewayGroupForm.vue'
import { listGatewayKeys, createGatewayKey, revokeGatewayKey, configureGatewayGroup, listGatewayGroups, updateGatewayGroup, deleteGatewayGroup, updateGatewayGroupQuota, getGatewayAnalytics, getGatewayRoutes, updateGatewayRoute, updateGatewayRouteStatus, deleteGatewayRoute, getGatewayCurrentConfig, listGatewayConfigVersions, getGatewayConfigVersion, createGatewayConfigDraft, activateGatewayConfigVersion, submitGatewayConfigVersion, approveGatewayConfigVersion, rejectGatewayConfigVersion, promoteGatewayConfigVersion, compareGatewayConfigVersion, rollbackGatewayConfigVersion, deleteGatewayConfigVersion } from '../../api/model'
const route = useRoute(), router = useRouter(), tabs = [{ id: 'overview', label: 'OVERVIEW', cn: '网关总览' }, { id: 'groups', label: 'MODEL GROUPS', cn: '模型分组' }, { id: 'keys', label: 'VIRTUAL KEYS', cn: '虚拟 Key' }, { id: 'releases', label: 'RELEASES', cn: '配置发布' }, { id: 'audit', label: 'AUDIT / HEALTH', cn: '运行观测' }]
const view = computed(() => ['groups', 'keys', 'audit', 'releases'].includes(route.query.view) ? route.query.view : 'overview'), unwrap = response => response?.data ?? response
const keys = ref([]), keysLoading = ref(false), keySaving = ref(false), keyBusy = ref(null), keyError = ref(''), keyNotice = ref(''), newKey = ref(''), groups = ref([]), groupsLoading = ref(false), groupSaving = ref(false), groupError = ref(''), groupNotice = ref(''), groupBusy = ref(null), routeDrafts = ref({})
const audit = ref({ summary: { calls: 0, successes: 0, latencyMs: 0, tokens: 0 }, recent: [] }), auditLoading = ref(false), auditError = ref(''), routeSlug = ref(''), routeHealth = ref([]), routeError = ref('')
const versions = ref([]), versionLoading = ref(false), versionBusy = ref(null), versionError = ref(''), versionNotice = ref(''), selectedVersion = ref(null), currentConfig = ref({})
const requiredApprovals = computed(() => Number(currentConfig.value.requiredApprovals) || 0)
const comparison = ref(null)
const successRate = computed(() => audit.value.summary.calls ? Math.round(audit.value.summary.successes / audit.value.summary.calls * 100) : 0)
function select(value) { router.replace({ path: '/model-gateway', query: value === 'overview' ? {} : { view: value } }) }
function quotaText(item) { return `${item.requestLimit24h > -1 ? item.requestLimit24h + ' req/24h' : 'unlimited requests'} · ${item.tokenLimit24h > -1 ? item.tokenLimit24h + ' tokens/24h' : 'unlimited tokens'}` }
function applyQuota(item, payload) { item.requestLimit24h = payload.requestLimit24h == null ? -1 : payload.requestLimit24h; item.tokenLimit24h = payload.tokenLimit24h == null ? -1 : payload.tokenLimit24h; keyNotice.value = 'Key 配额已更新。' }
async function loadKeys() { keysLoading.value = true; try { const value = unwrap(await listGatewayKeys()); keys.value = Array.isArray(value) ? value : (value?.items || []) } catch (error) { keyError.value = error.message || '无法读取 Key' } finally { keysLoading.value = false } }
async function createKey() { keySaving.value = true; keyError.value = ''; try { const value = unwrap(await createGatewayKey({ name: `personal-${new Date().toISOString().slice(0, 10)}` })); newKey.value = value.key; keyNotice.value = 'Key 已创建，请立即复制并保存。'; await loadKeys() } catch (error) { keyError.value = error.message || '创建 Key 失败' } finally { keySaving.value = false } }
async function revokeKey(item) { keyBusy.value = item.id; try { await revokeGatewayKey(item.id); item.revoked = true; keyNotice.value = 'Key 已撤销。' } catch (error) { keyError.value = error.message || '撤销 Key 失败' } finally { keyBusy.value = null } }
async function copyKey() { try { await navigator.clipboard.writeText(newKey.value); keyNotice.value = 'Key 已复制。' } catch { keyNotice.value = '请手动复制 Key。' } }
async function saveGroup(payload) { groupSaving.value = true; groupError.value = ''; try { await configureGatewayGroup(payload); await updateGatewayGroupQuota(payload.slug, { requestLimit24h: payload.requestLimit24h, tokenLimit24h: payload.tokenLimit24h }); groupNotice.value = '模型组和配额已保存。' } catch (error) { groupError.value = error.message || '保存模型组失败' } finally { groupSaving.value = false } }
async function loadAudit() { auditLoading.value = true; try { audit.value = unwrap(await getGatewayAnalytics()) } catch (error) { auditError.value = error.message || '无法读取网关统计' } finally { auditLoading.value = false } }
async function loadRouteHealth() { routeError.value = ''; try { routeHealth.value = unwrap(await getGatewayRoutes(routeSlug.value)) } catch (error) { routeError.value = error.message || '无法读取路由状态' } }
async function toggleRoute(item) { routeError.value = ''; try { await updateGatewayRouteStatus(routeSlug.value, item.id, !item.enabled); item.enabled = !item.enabled } catch (error) { routeError.value = error.message || '无法更新路由状态' } }
async function removeRoute(item) { routeError.value = ''; try { await deleteGatewayRoute(routeSlug.value, item.id); routeHealth.value = routeHealth.value.filter(route => route.id !== item.id) } catch (error) { routeError.value = error.message || '无法删除路由' } }
async function loadGroups() { groupsLoading.value = true; try { const value = unwrap(await listGatewayGroups()); groups.value = Array.isArray(value) ? value : (value?.items || []); routeDrafts.value = Object.fromEntries(groups.value.map(item => [item.id, { priority: 100, weight: 100 }])) } catch (error) { groupError.value = error.message || '无法读取模型组' } finally { groupsLoading.value = false } }
async function renameGroup(item) { const name = window.prompt('模型组名称', item.name); if (!name || name.trim() === item.name) return; groupBusy.value = item.slug; try { await updateGatewayGroup(item.slug, { name: name.trim() }); item.name = name.trim(); groupNotice.value = '模型组名称已更新。' } catch (error) { groupError.value = error.message || '无法更新模型组' } finally { groupBusy.value = null } }
async function removeGroup(item) { if (!window.confirm(`删除模型组 ${item.slug}？`)) return; groupBusy.value = item.slug; try { await deleteGatewayGroup(item.slug); groups.value = groups.value.filter(group => group.slug !== item.slug); groupNotice.value = '模型组已删除。' } catch (error) { groupError.value = error.message || '无法删除模型组' } finally { groupBusy.value = null } }
async function editRoute(group, routeItem) { const draft = routeDrafts.value[routeItem.id] || { priority: routeItem.priority, weight: routeItem.weight }; try { await updateGatewayRoute(group.slug, routeItem.id, { priority: Number(draft.priority), weight: Number(draft.weight) }); routeItem.priority = Number(draft.priority); routeItem.weight = Number(draft.weight); groupNotice.value = '路由参数已更新。' } catch (error) { groupError.value = error.message || '无法更新路由' } }
async function loadVersions() { versionLoading.value = true; versionError.value = ''; try { const list = unwrap(await listGatewayConfigVersions()); versions.value = Array.isArray(list) ? list : (list?.items || []); currentConfig.value = unwrap(await getGatewayCurrentConfig()) || {} } catch (error) { versionError.value = error.message || '无法读取配置版本' } finally { versionLoading.value = false } }
async function createVersion() { const summary = window.prompt('本次变更说明', '调整模型路由'); if (summary === null) return; versionBusy.value = 'create'; versionError.value = ''; try { const created = unwrap(await createGatewayConfigDraft({ summary })); selectedVersion.value = created; versionNotice.value = `已生成草稿 v${created.version}，确认差异后发布。`; await loadVersions() } catch (error) { versionError.value = error.message || '生成草稿失败' } finally { versionBusy.value = null } }
async function inspectVersion(item) { try { selectedVersion.value = unwrap(await getGatewayConfigVersion(item.id)) } catch (error) { versionError.value = error.message || '无法读取版本详情' } }
function statusText(item) { if (item.status === 'ACTIVE' && item.rolloutPercent < 100) return `CANARY ${item.rolloutPercent}%`; return item.status }
function verdictText(value) { return ({ PROMOTE: '可转全量', HOLD: '建议继续观察', ROLLBACK: '建议回滚', INSUFFICIENT_DATA: '样本不足，暂不下结论', NOT_CANARY: '不是灰度版本' })[value] || value }
async function compareVersion(item) { versionError.value = ''; try { comparison.value = unwrap(await compareGatewayConfigVersion(item.id, 60)) } catch (error) { versionError.value = error.message || '健康对比失败' } }
function promptPercent(action) { const raw = window.prompt(`${action}比例（1-100，100 表示全量）`, '100'); if (raw === null) return null; const value = Number(raw); if (!Number.isInteger(value) || value < 1 || value > 100) { window.alert('比例必须是 1-100 的整数'); return null } return value }
async function activateVersion(item) { const percent = promptPercent('发布'); if (percent === null) return; versionBusy.value = item.id; try { await activateGatewayConfigVersion(item.id, percent); versionNotice.value = percent < 100 ? `v${item.version} 已按 ${percent}% 灰度生效。` : `v${item.version} 已全量生效。`; await loadVersions() } catch (error) { versionError.value = error.message || '发布失败' } finally { versionBusy.value = null } }
async function submitVersion(item) { const percent = promptPercent('申请'); if (percent === null) return; versionBusy.value = item.id; try { await submitGatewayConfigVersion(item.id, { percent }); versionNotice.value = `v${item.version} 已提交审批。`; await loadVersions() } catch (error) { versionError.value = error.message || '提交审批失败' } finally { versionBusy.value = null } }
async function approveVersion(item) { const comment = window.prompt(`审批通过 v${item.version}，可填写备注`, ''); if (comment === null) return; versionBusy.value = item.id; try { await approveGatewayConfigVersion(item.id, { comment }); versionNotice.value = `已通过 v${item.version}。`; await loadVersions() } catch (error) { versionError.value = error.message || '审批失败' } finally { versionBusy.value = null } }
async function rejectVersion(item) { const comment = window.prompt(`驳回 v${item.version}，请填写原因`, ''); if (comment === null) return; versionBusy.value = item.id; try { await rejectGatewayConfigVersion(item.id, { comment }); versionNotice.value = `已驳回 v${item.version}。`; await loadVersions() } catch (error) { versionError.value = error.message || '驳回失败' } finally { versionBusy.value = null } }
async function promoteVersion(item) { if (!window.confirm(`把灰度 v${item.version} 提升为全量？`)) return; versionBusy.value = item.id; try { await promoteGatewayConfigVersion(item.id); versionNotice.value = `v${item.version} 已转全量。`; await loadVersions() } catch (error) { versionError.value = error.message || '转全量失败' } finally { versionBusy.value = null } }
async function rollbackVersion(item) { const reason = window.prompt(`以 v${item.version} 的内容回滚，填写原因`, '回滚'); if (reason === null) return; versionBusy.value = item.id; try { const created = unwrap(await rollbackGatewayConfigVersion(item.id, { reason })); versionNotice.value = `已回滚，新版本 v${created.version} 生效。`; await loadVersions() } catch (error) { versionError.value = error.message || '回滚失败' } finally { versionBusy.value = null } }
async function deleteVersion(item) { if (!window.confirm(`删除草稿 v${item.version}？`)) return; versionBusy.value = item.id; try { await deleteGatewayConfigVersion(item.id); versionNotice.value = '草稿已删除。'; await loadVersions() } catch (error) { versionError.value = error.message || '删除失败' } finally { versionBusy.value = null } }
onMounted(() => { if (view.value === 'keys') loadKeys(); if (view.value === 'audit') loadAudit(); if (view.value === 'groups') loadGroups(); if (view.value === 'releases') loadVersions() })
</script>
